  final String frecuencia;
  final int? diaSemana;
  final String? descripcion;
  final bool activo;
  final DateTime createdAt;
  final DateTime updatedAt;
  final bool synced;
  final DateTime? lastSyncAttempt;
  const Ruta({
    required this.id,
    required this.empresaId,
    required this.nombre,
    this.vendedor,
    required this.frecuencia,
    this.diaSemana,
