    map['nombre'] = Variable<String>(nombre);
    if (!nullToAbsent || vendedor != null) {
      map['vendedor'] = Variable<String>(vendedor);
    }
    map['frecuencia'] = Variable<String>(frecuencia);
    if (!nullToAbsent || diaSemana != null) {
      map['dia_semana'] = Variable<int>(diaSemana);
    }
    if (!nullToAbsent || descripcion != null) {
      map['descripcion'] = Variable<String>(descripcion);
    }
    map['activo'] = Variable<bool>(activo);
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    map['synced'] = Variable<bool>(synced);
    if (!nullToAbsent || lastSyncAttempt != null) {
      map['last_sync_attempt'] = Variable<DateTime>(lastSyncAttempt);
    }
    return map;
  }

  RutasCompanion toCompanion(bool nullToAbsent) {
    return RutasCompanion(
      id: Value(id),
      empresaId: Value(empresaId),
      nombre: Value(nombre),
      vendedor: vendedor == null && nullToAbsent
          ? const Value.absent()
          : Value(vendedor),
      frecuencia: Value(frecuencia),
      diaSemana: diaSemana == null && nullToAbsent
          ? const Value.absent()
          : Value(diaSemana),
      descripcion: descripcion == null && nullToAbsent
          ? const Value.absent()
          : Value(descripcion),
      activo: Value(activo),
      createdAt: Value(createdAt),
      updatedAt: Value(updatedAt),
      synced: Value(synced),
